//! The fork's Gruvppuccin plugin (`plugins/gruvppuccin/`, generated by
//! `scripts/gruvppuccin/generate.ts`) installs through the real plugin host: every theme
//! parses, merges its editor scheme and stays within the host's limits, and every icon
//! survives the SVG sanitiser.

use ide_host::plugins::*;
use ide_plugin::Limits;
use std::path::PathBuf;
use std::sync::Arc;

const ID: &str = "gruvppuccin";

fn plugin_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../plugins/gruvppuccin")
}

fn host(plugins_dir: PathBuf) -> PluginHost {
    let sink = |_client: Option<&str>, _event: PluginEvent| {};
    let host = PluginHost::new(plugins_dir, Arc::new(sink), Limits::default()).unwrap();
    host.load_all();
    host.startup_finished();
    host
}

#[test]
fn gruvppuccin_installs_with_63_themes_and_an_icon_theme() {
    let tmp = tempfile::tempdir().unwrap();
    let host = host(tmp.path().join("plugins"));
    let info = host.install_from_dir(&plugin_dir(), &Consent::all()).unwrap();
    assert_eq!(info.status, PluginStatus::Static, "{:?}", info.error);

    let themes: Vec<ThemeDef> = host
        .ui_items("themes")
        .into_iter()
        .filter(|c| c.plugin_id == ID)
        .map(|c| serde_json::from_value(c.decl).unwrap())
        .collect();
    assert_eq!(themes.len(), 63);
    assert_eq!(themes.iter().filter(|t| t.kind == ThemeKind::Light).count(), 15);

    for theme in &themes {
        let active = host.set_theme(Some((ID, &theme.id))).unwrap().unwrap();
        let tokens = &active.theme.tokens;
        // UI tokens, the merged editor scheme and the runtime's accent slots.
        for key in ["--bg-app", "--syn-keyword", "--ansi-red", "--gp-accent", "--syn-keyword-module", "--bg-editor"] {
            assert!(tokens.contains_key(key), "{}: {key}", theme.id);
        }
        assert!(tokens.len() > 280, "{}: {} tokens", theme.id, tokens.len());
    }

    let installed = host.info_of(ID).unwrap().path.0;
    assert!(installed.join("NOTICE").is_file());
    assert!(!installed.join("data/palettes.json").exists(), "only referenced files are installed");

    let items = host.ui_items("iconThemes");
    assert_eq!(items.len(), 1);
    let map: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(plugin_dir().join("icons/theme.json")).unwrap()).unwrap();
    let defined = map["iconDefinitions"].as_object().unwrap().len();
    let svgs = host.assets(ID, &icon_theme_svg_prefix("gruvppuccin")).unwrap();
    assert!(svgs.len() >= defined, "every icon survives the sanitiser: {} of {defined}", svgs.len());
}
